import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas = document.querySelector('#game-canvas');
const shell = document.querySelector('#game-shell');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.6));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#d5a77c');
scene.fog = new THREE.FogExp2('#c99e78', 0.0038);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 600);
const hemi = new THREE.HemisphereLight('#ffe3bd', '#584c3c', 2.0);
scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0d6', 3.2);
sun.position.set(-80, 120, 45);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.left = -100; sun.shadow.camera.right = 100; sun.shadow.camera.top = 100; sun.shadow.camera.bottom = -100;
scene.add(sun);

const mats = {};
function mat(name, color, roughness = 0.85, extra = {}) { return mats[name] = new THREE.MeshStandardMaterial({ color, roughness, ...extra }); }
mat('sand', '#b99470'); mat('road', '#454644'); mat('roadEdge', '#69665e'); mat('curbA', '#eee2cc'); mat('curbB', '#cf4e36');
mat('carBody', '#e65435', .37, { metalness: .35 }); mat('carDark', '#20272a', .48, { metalness: .4 });
mat('glass', '#263e43', .28, { metalness: .32, roughness: .25 }); mat('rubber', '#171819', .95); mat('rim', '#bcc0b9', .34, { metalness: .72 });
mat('yellow', '#e9b64d'); mat('concrete', '#b9aa93'); mat('building1', '#b88762'); mat('building2', '#d2ae84'); mat('building3', '#937866');
mat('palm', '#4b5a3c'); mat('trunk', '#70513a'); mat('white', '#f4e3c9'); mat('lamp', '#f5cb85', .45, { emissive: '#ab632d', emissiveIntensity: .45 });

const ground = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), mats.sand);
ground.rotation.x = -Math.PI / 2; ground.position.y = -0.16; ground.receiveShadow = true; scene.add(ground);
// Fine sand grain texture, generated locally so the game has no asset dependency.
const grainCanvas = document.createElement('canvas'); grainCanvas.width = grainCanvas.height = 256;
const gctx = grainCanvas.getContext('2d'); gctx.fillStyle = '#b99470'; gctx.fillRect(0,0,256,256);
for (let i=0;i<3200;i++){const a=Math.random()*.13;gctx.fillStyle=`rgba(${Math.random()>.5?'255,225,182':'73,53,35'},${a})`;gctx.fillRect(Math.random()*256,Math.random()*256,1+Math.random()*2,1)}
const sandTex = new THREE.CanvasTexture(grainCanvas); sandTex.wrapS=sandTex.wrapT=THREE.RepeatWrapping; sandTex.repeat.set(28,28); mats.sand.map=sandTex; mats.sand.needsUpdate=true;

// A wide, bank-free oval drift circuit.
const RX=69, RZ=43, TRACK=15;
function ovalStrip(innerOffset, outerOffset, material, y) {
  const points=[]; const n=240;
  for(let i=0;i<=n;i++){const a=i/n*Math.PI*2;points.push(new THREE.Vector3(Math.cos(a)*(RX+outerOffset),y,Math.sin(a)*(RZ+outerOffset)))}
  for(let i=n;i>=0;i--){const a=i/n*Math.PI*2;points.push(new THREE.Vector3(Math.cos(a)*(RX+innerOffset),y,Math.sin(a)*(RZ+innerOffset)))}
  const shape=new THREE.Shape(); shape.moveTo(points[0].x,points[0].z); for(let i=1;i<points.length;i++)shape.lineTo(points[i].x,points[i].z); shape.closePath();
  const geometry=new THREE.ShapeGeometry(shape,1); geometry.rotateX(-Math.PI/2);
  const mesh=new THREE.Mesh(geometry,material); mesh.position.y=y; mesh.receiveShadow=true; scene.add(mesh); return mesh;
}
ovalStrip(-TRACK/2, TRACK/2, mats.road, -.105);
ovalStrip(-TRACK/2-1.6, -TRACK/2, mats.roadEdge, -.10);
ovalStrip(TRACK/2, TRACK/2+1.6, mats.roadEdge, -.10);
// Dashed center line on the asphalt.
const dashMat = new THREE.MeshStandardMaterial({color:'#d7c6a9',roughness:1});
for(let i=0;i<68;i++){const a=i/68*Math.PI*2;const dash=new THREE.Mesh(new THREE.BoxGeometry(2.15,.025,.14),dashMat);dash.position.set(Math.cos(a)*RX,.025,Math.sin(a)*RZ);dash.rotation.y=-a;scene.add(dash)}
// Alternating curb blocks along both track edges.
for(let i=0;i<168;i++){const a=i/168*Math.PI*2; for(const side of [-1,1]){const rX=RX+side*(TRACK/2+0.65),rZ=RZ+side*(TRACK/2+0.65);const curb=new THREE.Mesh(new THREE.BoxGeometry(2.65,.18,.72),i%2?mats.curbA:mats.curbB);curb.position.set(Math.cos(a)*rX,.015,Math.sin(a)*rZ);curb.rotation.y=-a;scene.add(curb)}}

// Low-poly desert city and track-side fixtures.
const boxGeo=new THREE.BoxGeometry(1,1,1);
function building(x,z,w,h,d,material,angle=0){const b=new THREE.Mesh(boxGeo,material);b.position.set(x,h/2-.02,z);b.scale.set(w,h,d);b.rotation.y=angle;b.castShadow=true;b.receiveShadow=true;scene.add(b);
 const roof=new THREE.Mesh(new THREE.BoxGeometry(w*1.04,.45,d*1.04),mats.concrete);roof.position.set(x,h+.18,z);roof.rotation.y=angle;scene.add(roof);
 for(let y=2.3;y<h-1;y+=3.1){for(let xx=-w/2+1.5;xx<w/2-1;xx+=3){const win=new THREE.Mesh(new THREE.BoxGeometry(1.05,1.35,.08),mats.glass);win.position.set(x+xx,y,z-d/2-.045);win.rotation.y=angle;scene.add(win)}}
}
const district=[[-145,-55,19,29,18],[-119,-102,28,44,21],[-89,-137,24,34,19],[-42,-148,34,55,22],[22,-151,27,42,18],[70,-140,25,34,21],[127,-109,28,47,18],[152,-53,33,38,25],[150,10,26,32,20],[121,82,27,43,21],[77,133,33,51,24],[19,147,29,34,20],[-44,145,24,42,19],[-103,116,31,37,22],[-147,67,22,32,17]];
district.forEach((v,i)=>building(v[0],v[1],v[2],v[3],v[4],[mats.building1,mats.building2,mats.building3][i%3],(i%4-2)*.08));
for(let i=0;i<38;i++){const a=i/38*Math.PI*2;const x=Math.cos(a)*(RX+TRACK/2+7),z=Math.sin(a)*(RZ+TRACK/2+7);const pole=new THREE.Mesh(new THREE.CylinderGeometry(.13,.18,7,6),mats.carDark);pole.position.set(x,3.5,z);scene.add(pole);const arm=new THREE.Mesh(new THREE.BoxGeometry(1.6,.12,.12),mats.carDark);arm.position.set(x+.55,6.6,z);scene.add(arm);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.22,8,6),mats.lamp);bulb.position.set(x+1.25,6.45,z);scene.add(bulb)}
// Desert palms as simple sculptural silhouettes.
function palm(x,z,s=1){const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(s);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.22,.38,5.4,6),mats.trunk);trunk.position.y=2.7;trunk.rotation.z=-.08;group.add(trunk);for(let i=0;i<8;i++){const a=i/8*Math.PI*2;const leaf=new THREE.Mesh(new THREE.ConeGeometry(.34,4.2,5),mats.palm);leaf.position.set(Math.cos(a)*1.5,5.1+Math.sin(i*7)*.15,Math.sin(a)*1.5);leaf.rotation.z=Math.cos(a)*-.72;leaf.rotation.x=Math.sin(a)*.72;group.add(leaf)}scene.add(group)}
[[-98,7],[-87,19],[-109,-2],[104,17],[111,1],[93,24],[-6,-68],[24,-66]].forEach((p,i)=>palm(p[0],p[1],.75+(i%3)*.14));

// Start/finish gantry and graphic boards.
const gate=new THREE.Group();gate.position.set(0,0,-RZ);scene.add(gate);
for(const x of [-10.5,10.5]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.8,8,.8),mats.carDark);leg.position.set(x,4,0);gate.add(leg)}
const beam=new THREE.Mesh(new THREE.BoxGeometry(22,1.2,1.3),mats.carDark);beam.position.y=8;gate.add(beam);
const sign=new THREE.Mesh(new THREE.BoxGeometry(8,2.4,.4),mats.carBody);sign.position.set(0,6.8,-.72);gate.add(sign);

// Sport sedan assembled from clean geometric parts.
const car=new THREE.Group();scene.add(car);
const shellBody=new THREE.Mesh(new THREE.BoxGeometry(2.55,.72,4.7),mats.carBody);shellBody.position.y=.79;shellBody.castShadow=true;car.add(shellBody);
const cabin=new THREE.Mesh(new THREE.BoxGeometry(1.93,.77,2.15),mats.glass);cabin.position.set(0,1.47,-.15);cabin.castShadow=true;car.add(cabin);
const roof=new THREE.Mesh(new THREE.BoxGeometry(1.72,.13,1.55),mats.carBody);roof.position.set(0,1.88,-.25);car.add(roof);
const hood=new THREE.Mesh(new THREE.BoxGeometry(2.35,.16,1.08),mats.carBody);hood.position.set(0,1.15,-1.47);car.add(hood);
const bumper=new THREE.Mesh(new THREE.BoxGeometry(2.62,.28,.22),mats.carDark);bumper.position.set(0,.52,-2.36);car.add(bumper);
const rearBumper=bumper.clone();rearBumper.position.z=2.36;car.add(rearBumper);
for(const x of [-.83,.83]){const light=new THREE.Mesh(new THREE.BoxGeometry(.48,.22,.11),mats.lamp);light.position.set(x,1.04,-2.36);car.add(light);const tail=new THREE.Mesh(new THREE.BoxGeometry(.5,.2,.11),new THREE.MeshStandardMaterial({color:'#ff3e2e',emissive:'#6d140e'}));tail.position.set(x,1.02,2.37);car.add(tail)}
const wheels=[];
for(const x of [-1.25,1.25])for(const z of [-1.52,1.55]){const wheel=new THREE.Group();wheel.position.set(x,.49,z);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.46,.46,.32,16),mats.rubber);tire.rotation.z=Math.PI/2;tire.castShadow=true;wheel.add(tire);const rim=new THREE.Mesh(new THREE.CylinderGeometry(.25,.25,.34,12),mats.rim);rim.rotation.z=Math.PI/2;wheel.add(rim);car.add(wheel);wheels.push({group:wheel,front:z<0})}
const spoiler=new THREE.Mesh(new THREE.BoxGeometry(2.2,.1,.38),mats.carDark);spoiler.position.set(0,1.62,2.08);car.add(spoiler);
const shadow=new THREE.Mesh(new THREE.CircleGeometry(2,20),new THREE.MeshBasicMaterial({color:'#161514',transparent:true,opacity:.27,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.03;car.add(shadow);

