input.newString:
function ovalStrip(innerOffset, outerOffset, material, y) {
  const shape=new THREE.Shape();
  shape.absellipse(0, 0, RX+outerOffset, RZ+outerOffset, 0, Math.PI*2, false, 0);
  const hole = new THREE.Path();
  hole.absellipse(0, 0, RX+innerOffset, RZ+innerOffset, 0, Math.PI*2, true, 0);
  shape.holes.push(hole);
  const geometry=new THREE.ShapeGeometry(shape,2); geometry.rotateX(-Math.PI/2);
  const mesh=new THREE.Mesh(geometry,material); mesh.position.y=y; mesh.receiveShadow=true; scene.add(mesh); return mesh;
}

