// Drifting smoke puffs, emitted from the rear wheels.
const smokeCanvas=document.createElement('canvas');smokeCanvas.width=smokeCanvas.height=64;
const sctx=smokeCanvas.getContext('2d');const grad=sctx.createRadialGradient(32,32,1,32,32,31);grad.addColorStop(0,'rgba(226,220,207,.58)');grad.addColorStop(.45,'rgba(206,198,184,.25)');grad.addColorStop(1,'rgba(180,173,161,0)');sctx.fillStyle=grad;sctx.fillRect(0,0,64,64);
const smokeTexture=new THREE.CanvasTexture(smokeCanvas);
const smoke=[];
for(let i=0;i<24;i++){const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:smokeTexture,transparent:true,depthWrite:false,opacity:0}));sprite.scale.set(1,1,1);scene.add(sprite);smoke.push({sprite,life:0})}
let smokeCursor=0;

const input={left:false,right:false,throttle:false,brake:false,handbrake:false};
const velocity=new THREE.Vector3();
const clock=new THREE.Clock();
let running=false,paused=false,elapsed=0,score=0,banked=0,driftChain=0,chainMultiplier=1,lastToast=0;
let best=Number(localStorage.getItem('hajwala-best')||0);
document.querySelector('#best').textContent=String(best).padStart(6,'0');
car.position.set(RX,0,0);car.rotation.y=Math.PI;
const ui={score:document.querySelector('#score'),plus:document.querySelector('#score-plus'),combo:document.querySelector('#combo'),speed:document.querySelector('#speed'),speedFill:document.querySelector('#speed-fill'),angle:document.querySelector('#angle'),angleFill:document.querySelector('#angle-fill'),timer:document.querySelector('#timer'),callout:document.querySelector('#callout'),toast:document.querySelector('#toast'),gear:document.querySelector('#gear')};

function clamp(v,min,max){return Math.max(min,Math.min(max,v))}
function wrapAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;return a}
function formatTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function trackOffset(x,z){return (Math.sqrt((x/RX)**2+(z/RZ)**2)-1)*((RX+RZ)*.5)}
function showToast(label,amount){ui.toast.innerHTML=`${label} <span>+${amount}</span>`;ui.toast.classList.add('visible');setTimeout(()=>ui.toast.classList.remove('visible'),950)}
function resetRun(){elapsed=0;score=0;banked=0;driftChain=0;chainMultiplier=1;velocity.set(0,0,0);car.position.set(RX,0,0);car.rotation.y=Math.PI;ui.score.textContent='000000';ui.plus.textContent='';ui.combo.textContent='FIND YOUR ANGLE';}
function begin(){if(!running){running=true;paused=false;resetRun();document.querySelector('#start-overlay').classList.add('hidden')}else if(paused){paused=false;document.querySelector('#pause-overlay').classList.add('hidden');shell.classList.remove('paused')}}
function togglePause(){if(!running)return;paused=!paused;document.querySelector('#pause-overlay').classList.toggle('hidden',!paused);shell.classList.toggle('paused',paused)}
document.querySelector('#start-btn').addEventListener('click',begin);
document.querySelector('#resume-btn').addEventListener('click',togglePause);
document.querySelector('#pause-btn').addEventListener('click',togglePause);

const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'throttle',KeyW:'throttle',ArrowDown:'brake',KeyS:'brake',Space:'handbrake'};
window.addEventListener('keydown',e=>{if(e.code==='Escape'||e.code==='KeyP'){togglePause();return}if(e.code==='Enter'&&!running){begin();return}const key=keyMap[e.code];if(key){e.preventDefault();input[key]=true}});
window.addEventListener('keyup',e=>{const key=keyMap[e.code];if(key)input[key]=false});
window.addEventListener('blur',()=>Object.keys(input).forEach(k=>input[k]=false));
document.querySelectorAll('[data-control]').forEach(button=>{
  const key=button.dataset.control;
  const release=e=>{e.preventDefault();input[key]=false;button.classList.remove('pressed')};
  button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);input[key]=true;button.classList.add('pressed')});
  button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);
});
let muted=false;document.querySelector('#sound-btn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♪':'♫';e.currentTarget.style.opacity=muted?'.55':'1'});

function update(dt){
  if(!running||paused)return;
  elapsed+=dt;const speed=velocity.length();
  const steer=(input.left?1:0)-(input.right?1:0);
  const throttle=input.throttle?1:0, brake=input.brake?1:0, hand=input.handbrake?1:0;
  const maxSpeed=38;
  let forwardX=-Math.sin(car.rotation.y),forwardZ=-Math.cos(car.rotation.y);
  // Throttle, brake and handbrake have distinct arcade handling.
  const acceleration=throttle*24-brake*34-(throttle?0:3.4);
  velocity.x+=forwardX*acceleration*dt;velocity.z+=forwardZ*acceleration*dt;
  if(speed>.8){const turn=steer*(.52+Math.min(speed,28)*.039)*(hand?1.32:1);car.rotation.y+=turn*dt*(velocity.dot(new THREE.Vector3(forwardX,0,forwardZ))>=0?1:-.55)}
  forwardX=-Math.sin(car.rotation.y);forwardZ=-Math.cos(car.rotation.y);
  const forwardSpeed=velocity.x*forwardX+velocity.z*forwardZ;
  const rightX=Math.cos(car.rotation.y),rightZ=-Math.sin(car.rotation.y);
  let sideSpeed=velocity.x*rightX+velocity.z*rightZ;
  if(hand&&speed>5&&steer!==0)sideSpeed+=steer*speed*.42*dt;
  const lateralGrip=hand?.12:.92;
  sideSpeed*=Math.max(0,1-lateralGrip*dt);
  let newForward=forwardSpeed;
  if(brake)newForward*=Math.max(0,1-1.6*dt);
  const drag=1-(throttle?.12:.27)*dt;newForward*=drag;sideSpeed*=1-.09*dt;
  velocity.x=forwardX*newForward+rightX*sideSpeed;
  velocity.z=forwardZ*newForward+rightZ*sideSpeed;
  if(velocity.length()>maxSpeed)velocity.setLength(maxSpeed);
  car.position.x+=velocity.x*dt;car.position.z+=velocity.z*dt;
  // Keep the session on the circuit: sand slows the car without an abrupt reset.
  const off=trackOffset(car.position.x,car.position.z);
  if(Math.abs(off)>10.5){velocity.multiplyScalar(Math.max(.88,1-1.6*dt));}
  if(Math.abs(car.position.x)>125||Math.abs(car.position.z)>99){velocity.multiplyScalar(.94);car.position.x=clamp(car.position.x,-124,124);car.position.z=clamp(car.position.z,-98,98)}
  car.position.y=0;
  for(const w of wheels){w.group.rotation.x-=speed*dt*1.7;if(w.front)w.group.rotation.y=steer*.3}
  const velocityAngle=speed>.3?Math.atan2(-velocity.x,-velocity.z):car.rotation.y;
  const drift=wrapAngle(velocityAngle-car.rotation.y);const angleDeg=Math.round(Math.abs(drift)*180/Math.PI);
  const inDrift=speed>7&&angleDeg>11&&angleDeg<72&&Math.abs(off)<10.3;
  if(inDrift){driftChain+=dt;chainMultiplier=clamp(1+Math.floor(driftChain/2),1,5);const points=Math.round((speed*2.15+angleDeg*1.45)*chainMultiplier*dt);score+=points;banked+=points;ui.score.textContent=String(Math.floor(score)).padStart(6,'0');ui.plus.textContent=`+${Math.floor(points)}`;ui.combo.textContent=`${chainMultiplier>1?`${chainMultiplier}× MULTIPLIER  ·  `:''}${angleDeg>35?'BIG ANGLE':'CLEAN SLIDE'}`;ui.combo.style.color='#ffbd75';
    if(elapsed-lastToast>4&&driftChain>1){showToast(angleDeg>38?'BIG ANGLE':'NICE LINE',Math.floor(points*3));lastToast=elapsed}
  }else if(driftChain>0){driftChain=0;chainMultiplier=1;banked=0;ui.combo.textContent='FIND YOUR ANGLE';ui.combo.style.color=''}
  // Rear tire smoke when the car is properly stepped out.
  if(inDrift&&Math.random()<.42){const i=smokeCursor++%smoke.length;const p=smoke[i];const side= Math.random()<.5?-.85:.85;const c=Math.cos(car.rotation.y),s=Math.sin(car.rotation.y);p.sprite.position.set(car.position.x+c*side+Math.random()*.4,.65,car.position.z-s*side+Math.random()*.4);p.life=1.15;p.sprite.material.opacity=.52;p.sprite.scale.setScalar(.7+Math.random()*.6)}
  for(const p of smoke){if(p.life>0){p.life-=dt;p.sprite.position.y+=dt*.48;p.sprite.scale.multiplyScalar(1+dt*.45);p.sprite.material.opacity=Math.max(0,p.life/1.15*.45)}}
  // Chase camera eases behind the car and looks toward its next line.
  const camDistance=9.6,camHeight=5.1;const behindX=Math.sin(car.rotation.y)*camDistance,behindZ=Math.cos(car.rotation.y)*camDistance;
  const targetPos=new THREE.Vector3(car.position.x+behindX,camHeight,car.position.z+behindZ);
  camera.position.lerp(targetPos,1-Math.exp(-4.5*dt));
  camera.lookAt(car.position.x+forwardX*4,1.05,car.position.z+forwardZ*4);
  const kmh=Math.round(speed*3.6);ui.speed.textContent=kmh;ui.speedFill.style.width=`${clamp(kmh/150*100,0,100)}%`;ui.angle.textContent=`${angleDeg}°`;ui.angleFill.style.width=`${clamp(angleDeg/60*100,0,100)}%`;ui.timer.textContent=formatTime(elapsed);ui.gear.textContent=speed<1?'N':(speed<13?'1':speed<25?'2':'3');
  ui.callout.classList.toggle('show',hand&&speed>4);
