const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
 const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
 page.on('pageerror',e=>console.log('PAGEERROR',e.message));
 page.on('console',m=>{if(m.type()==='error')console.log('CONSOLE',m.text())});
 await page.goto('http://localhost:3002',{waitUntil:'load'}); await page.waitForTimeout(1200);
 await page.screenshot({path:'/tmp/opencode/hajwala.jpg',type:'jpeg',quality:75});
 console.log('Initial', await page.locator('#start-overlay').evaluate(e=>getComputedStyle(e).display), await page.locator('#game-canvas').evaluate(e=>[e.width,e.height]));
 await page.locator('#start-btn').click();
 await page.keyboard.down('ArrowUp'); await page.waitForTimeout(1800); await page.keyboard.up('ArrowUp');
 await page.keyboard.down('Space'); await page.keyboard.down('ArrowLeft'); await page.waitForTimeout(2500); await page.keyboard.up('Space'); await page.keyboard.up('ArrowLeft');
 await page.waitForTimeout(2500);
 console.log('Gameplay', {speed:await page.locator('#speed').innerText(),score:await page.locator('#score').innerText(),angle:await page.locator('#angle').innerText(),timer:await page.locator('#timer').innerText()});
 await page.locator('#pause-btn').click(); console.log('Paused',await page.locator('#pause-overlay').evaluate(e=>!e.classList.contains('hidden')));
 await page.locator('#resume-btn').click(); console.log('Resumed',await page.locator('#pause-overlay').evaluate(e=>e.classList.contains('hidden')));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
