* {
box-sizing:border-box}
 :root {
--ink:#f3eee1;--muted:#a9aaa2;--orange:#ff713d;--dark:#101619}
 html,body {
margin:0;width:100%;height:100%;overflow:hidden;background:#111719;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none}
#game-shell {
