.topbar {
position:absolute;left:0;right:0;top:0;padding:clamp(16px,2.6vw,32px) clamp(18px,4.2vw,64px);display:flex;align-items:center;justify-content:space-between}
.brand {
display:flex;gap:11px;align-items:center;color:var(--ink);text-decoration:none;font-family:'Barlow Condensed',sans-serif;font-weight:900;letter-spacing:1.6px;font-size:21px;line-height:.9}
.brand small {
display:block;color:#b9b8ad;font:600 8px 'DM Sans',sans-serif;letter-spacing:2px;margin-top:6px}
.brand-mark {
width:37px;height:37px;border:1px solid rgba(255,255,255,.55);display:grid;place-items:center;color:var(--orange);font:900 24px 'Barlow Condensed';transform:skew(-8deg)}
.top-actions {
display:flex;align-items:center;gap:12px}
.weather {
font-size:10px;font-weight:700;letter-spacing:1.2px;color:#ddd9cd;margin-right:8px}
.weather b {
color:#fff;margin-left:10px}
.sun-icon {
font-size:17px;color:#ffc679;vertical-align:-2px;margin-right:6px}
.icon-btn {
width:37px;height:37px;border:1px solid rgba(255,255,255,.3);background:rgba(17,24,24,.35);color:white;font-size:16px;border-radius:50%;cursor:pointer;backdrop-filter:blur(8px)}
.icon-btn:hover {
background:var(--orange);border-color:var(--orange)}
.hud {
position:absolute;left:clamp(20px,5vw,76px);top:clamp(90px,16vh,160px);display:flex;gap:64px;align-items:flex-end;text-shadow:0 2px 12px #24201c}
.eyebrow,.stat-label,.meter-head {
font-size:9px;letter-spacing:2px;font-weight:700;color:#e4d8c6}
.live-dot {
display:inline-block;width:6px;height:6px;border-radius:50%;background:#ff7545;margin:0 7px 1px 0;box-shadow:0 0 8px #f76b3d}
.score-line {
