.run-stats {
display:flex;gap:20px;align-items:center;padding-bottom:5px}
.run-stats>div:not(.divider) {
display:flex;flex-direction:column;gap:5px}
.stat-label {
font-size:8px;color:#c5b7a3}
.run-stats strong {
font:700 18px 'Barlow Condensed';letter-spacing:1px}
.divider {
