.intro-card h1 em,.pause-card h2 em {
font-style:italic;color:var(--orange)}
.intro-card p {
color:#d0ccc0;font-size:12px;line-height:1.7;margin:0 0 18px}
.howto {
display:flex;align-items:center;justify-content:center;gap:5px;margin:0 auto 20px}
.keycap {
height:25px;min-width:24px;padding:0 6px;display:grid;place-items:center;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);border-radius:4px;font-size:10px;font-weight:700;color:white}
.keycap.wide {
