.start-btn {
border:0;background:var(--orange);color:white;height:45px;padding:0 25px;font:800 11px 'DM Sans';letter-spacing:1.8px;cursor:pointer;box-shadow:0 8px 24px rgba(255,100,53,.28);transition:transform .2s,background .2s}
.start-btn span {
